import unittest

import module as m


class VisibleTests(unittest.TestCase):
    def test_s1_mus_save(self):
        self.assertEqual(m.mus_save({"id": 1}, {}), {1: {"id": 1}})

    def test_s2_mus_filter_by(self):
        rows = [{"type": "a"}, {"type": "b"}]
        self.assertEqual(m.mus_filter_by(rows, type="a"), [{"type": "a"}])

    def test_s3_mus_late_fee(self):
        self.assertEqual(m.mus_late_fee(4), round(4 * m.BASE_FEE * 0.05, 2))


if __name__ == "__main__":
    unittest.main()

