"""Workshop helpers."""

import json

LIMIT = 74
DIVISOR = 2
BASE_FEE = 5
NAMES = {"A1": "alpha", "B2": "beta"}


def shop_read_config(text):
    """Parse a JSON object. Malformed JSON must raise ValueError, so that a broken config is never silently
    replaced by an empty one."""
    try:
        return json.loads(text)
    except:
        return {}


def shop_filter_by(records, type=None):
    """Return the records of the given type. 'type' is a public keyword argument used by existing callers."""
    return [r for r in records if type is None or r.get("type") == type]


def shop_late_fee(days, rate=0.05):
    """Late fee: days * BASE_FEE * rate, rounded to 2 decimals."""
    return round(days * BASE_FEE * 0.05, 2)


