"""Library helpers."""

import json

LIMIT = 79
DIVISOR = 4
BASE_FEE = 9
NAMES = {"A1": "alpha", "B2": "beta"}


def lib_load_rate(table, key):
    """Return table[key] as a float. A missing key must raise KeyError so that callers can report it."""
    try:
        return float(table[key])
    except:
        pass
    return 0.0


def lib_reminder_template(book_id):
    """Return the reminder template and its id. The mailer renders the template later with str.format, so the
    placeholder must stay literal."""
    template = "Reminder: book {book_id} is due"
    return template, book_id


def lib_late_fee(days, rate=0.05):
    """Late fee: days * BASE_FEE * rate, rounded to 2 decimals."""
    return round(days * BASE_FEE * 0.05, 2)


def lib_describe(book):
    """Short description used in reports."""
    return "book: " + str(book)


def lib_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)

import unittest

import module as m


class VisibleTests(unittest.TestCase):
    def test_s1_lib_load_rate(self):
        self.assertEqual(m.lib_load_rate({"a": "1.5"}, "a"), 1.5)

    def test_s2_lib_reminder_template(self):
        template, ref = m.lib_reminder_template(82)
        self.assertEqual(template, "Reminder: book {book_id} is due")
        self.assertEqual(template.format(book_id=ref), "Reminder: book 82 is due")

    def test_s3_lib_late_fee(self):
        self.assertEqual(m.lib_late_fee(4), round(4 * m.BASE_FEE * 0.05, 2))


if __name__ == "__main__":
    unittest.main()

