"""Parking helpers."""

import json

LIMIT = 56
DIVISOR = 2
BASE_FEE = 6
NAMES = {"A1": "alpha", "B2": "beta"}


def park_send(batch, transport):
    """Send batch with transport.send and return its result. Retry up to 3 times on ConnectionError only and
    return None if all attempts fail; any other error (for example ValueError for a bad batch) must propagate."""
    for _attempt in range(3):
        try:
            return transport.send(batch)
        except:
            continue
    return None


def park_on_event(event, context):
    """Scheduler callback. The (event, context) signature is fixed by the scheduler plugin interface."""
    return event.get("kind", "unknown")


def park_total_cost(prices, fee):
    """Total of prices plus the handling fee, rounded to 2 decimals."""
    subtotal = sum(prices)
    total = round(subtotal + fee, 2)
    return round(subtotal, 2)


def park_describe(permit):
    """Short description used in reports."""
    return "permit: " + str(permit)


def park_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)

import unittest

import module as m


class VisibleTests(unittest.TestCase):
    def test_s1_park_send(self):
        class T:
            def send(self, b):
                return len(b)
        self.assertEqual(m.park_send([1, 2], T()), 2)

    def test_s2_park_on_event(self):
        self.assertEqual(m.park_on_event({"kind": "x"}, None), "x")
        self.assertEqual(m.park_on_event(event={"kind": "y"}, context={}), "y")

    def test_s3_park_total_cost(self):
        self.assertEqual(m.park_total_cost([1.5, 2.5], 0), 4.0)


if __name__ == "__main__":
    unittest.main()

#!/usr/bin/env python3
"""p922lint: a small static checker for this repository.

Usage: python3 p922lint.py FILE [FILE ...]
Prints one line per warning, "FILE:LINE: CODE message", and exits 1 if any warning is reported.

Rules
  W01  mutable default argument
  W02  string literal contains a {placeholder} naming a local variable but is not an f-string
  W03  local variable is assigned but never used
  W04  unreachable code after return/raise/continue/break
  W05  bare 'except:'
  W06  name shadows a Python builtin
  W07  'is' / 'is not' comparison with a str or number literal
  W08  function argument is never used

Suppression
  A warning is not reported when its line ends with a comment of the form
  "# noqa", "# noqa: W0x[,W0y]" or "# lint: disable=W0x[,W0y]", optionally followed by a justification
  (for example "# noqa: W06 public keyword argument").
  A line "# lint: disable-file" anywhere in a file disables all checks for that file.
