#!/usr/bin/env python3
"""p922lint: a small static checker for this repository.

Usage: python3 p922lint.py FILE [FILE ...]
Prints one line per warning, "FILE:LINE: CODE message", and exits 1 if any warning is reported.

Rules
  W01  mutable default argument
  W02  string literal contains a {placeholder} naming a local variable but is not an f-string
  W03  local variable is assigned but never used
  W04  unreachable code after return/raise/continue/break
  W05  bare 'except:'
  W06  name shadows a Python builtin
  W07  'is' / 'is not' comparison with a str or number literal
  W08  function argument is never used

Suppression
  A warning is not reported when its line ends with a comment of the form
  "# noqa", "# noqa: W0x[,W0y]" or "# lint: disable=W0x[,W0y]", optionally followed by a justification
  (for example "# noqa: W06 public keyword argument").
  A line "# lint: disable-file" anywhere in a file disables all checks for that file.
"""
import ast
import builtins
import re
import sys

BUILTINS = {n for n in dir(builtins) if not n.startswith('_')}
PLACEHOLDER = re.compile(r'\{([A-Za-z_][A-Za-z0-9_]*)\}')
NOQA = re.compile(r'#\s*(?:noqa(?::\s*(?P<a>[A-Z]\d\d(?:\s*,\s*[A-Z]\d\d)*))?|lint:\s*disable=(?P<b>[A-Z]\d\d(?:\s*,\s*[A-Z]\d\d)*))(?![A-Za-z0-9=:,-]).*$')


def suppressed(lines, lineno, code):
    if not 1 <= lineno <= len(lines):
        return False
    m = NOQA.search(lines[lineno - 1])
    if not m:
        return False
    codes = m.group('a') or m.group('b')
    if codes is None:
        return True
    return code in {c.strip() for c in codes.split(',')}


def func_nodes(fn):
    """Nodes that belong to fn itself (not to nested functions, classes or lambdas)."""
    out, stack = [], list(ast.iter_child_nodes(fn))
    while stack:
        n = stack.pop()
        out.append(n)
        if not isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Lambda)):
            stack.extend(ast.iter_child_nodes(n))
    return out


def check_function(fn, warn):
    args = fn.args.posonlyargs + fn.args.args + fn.args.kwonlyargs
    if fn.args.vararg:
        args.append(fn.args.vararg)
    if fn.args.kwarg:
        args.append(fn.args.kwarg)
    for d in fn.args.defaults + [d for d in fn.args.kw_defaults if d is not None]:
        if isinstance(d, (ast.List, ast.Dict, ast.Set)) or (
                isinstance(d, ast.Call) and isinstance(d.func, ast.Name) and d.func.id in ('list', 'dict', 'set')):
            warn(fn.lineno, 'W01', 'mutable default argument in %s()' % fn.name)
    nodes = func_nodes(fn)
    loads = {n.id for n in nodes if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Load)}
    stores = {}
    for n in nodes:
        if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Store):
            stores.setdefault(n.id, n.lineno)
    for a in args:
        if a.arg in BUILTINS:
            warn(fn.lineno, 'W06', "argument '%s' shadows a builtin" % a.arg)
    for name, line in stores.items():
        if name in BUILTINS:
            warn(line, 'W06', "variable '%s' shadows a builtin" % name)
    trivial = all(isinstance(s, ast.Pass) or (isinstance(s, ast.Expr) and isinstance(s.value, ast.Constant))
                  for s in fn.body)
    if not trivial:
        for a in args:
            if a.arg in ('self', 'cls') or a.arg.startswith('_'):
                continue
            if a.arg not in loads:
                warn(fn.lineno, 'W08', "argument '%s' of %s() is never used" % (a.arg, fn.name))
    for name, line in stores.items():
        if not name.startswith('_') and name not in loads:
            warn(line, 'W03', "local variable '%s' is assigned but never used" % name)
    local_names = {a.arg for a in args} | set(stores)
    formatted = set()
    for n in nodes:
        if isinstance(n, ast.Attribute) and n.attr in ('format', 'format_map') and isinstance(n.value, ast.Constant):
            formatted.add(id(n.value))
    joined = {id(v) for n in nodes if isinstance(n, ast.JoinedStr) for v in n.values}
    for n in nodes:
        if isinstance(n, ast.Constant) and isinstance(n.value, str) and id(n) not in formatted and id(n) not in joined:
            names = [p for p in PLACEHOLDER.findall(n.value) if p in local_names]
            if names:
                warn(n.lineno, 'W02', "string contains {%s} but is not an f-string" % names[0])


def check_blocks(tree, warn):
    for n in ast.walk(tree):
        for field in ('body', 'orelse', 'finalbody'):
            block = getattr(n, field, None)
            if not isinstance(block, list):
                continue
            for i, s in enumerate(block[:-1]):
                if isinstance(s, (ast.Return, ast.Raise, ast.Continue, ast.Break)):
                    warn(block[i + 1].lineno, 'W04', 'unreachable code')
                    break
        if isinstance(n, ast.ExceptHandler) and n.type is None:
            warn(n.lineno, 'W05', "bare 'except:'")
        if isinstance(n, ast.Compare):
            for op, right in zip(n.ops, n.comparators):
                if isinstance(op, (ast.Is, ast.IsNot)) and isinstance(right, ast.Constant) and \
                        isinstance(right.value, (str, int, float)) and not isinstance(right.value, bool):
                    warn(n.lineno, 'W07', "'is' comparison with a literal")


def lint(path):
    src = open(path, encoding='utf-8').read()
    lines = src.splitlines()
    if any(re.match(r'\s*#\s*lint:\s*disable-file\s*$', l) for l in lines):
        return []
    try:
        tree = ast.parse(src, filename=path)
    except SyntaxError as e:
        return ['%s:%s: E00 syntax error: %s' % (path, e.lineno, e.msg)]
    found = []

    def warn(line, code, msg):
        if not suppressed(lines, line, code):
            found.append((line, code, msg))
    for n in ast.walk(tree):
        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)):
            check_function(n, warn)
    check_blocks(tree, warn)
    return ['%s:%d: %s %s' % (path, l, c, m) for l, c, m in sorted(set(found))]


if __name__ == '__main__':
    out = [w for p in sys.argv[1:] for w in lint(p)]
    print('\n'.join(out) if out else 'p922lint: no warnings')
    sys.exit(1 if out else 0)

#!/usr/bin/env python3
"""contract_check: flags exception handlers that swallow an exception the function's docstring says must be raised.

Static and deterministic (no model, no test generation). For every function whose docstring states an obligation such as
"must raise KeyError", "raise ValueError for ...", "... must raise ValueError" or "any other error (for example ValueError)
must propagate", every `except` clause in that function that can catch a documented exception (the same class, a base
class or subclass, `Exception`/`BaseException`, or a bare `except:`), is the first such handler of its `try`, and whose
body contains no `raise` is reported:

  module.py:LINE: C01 handler swallows ValueError, which the docstring of FUNC says must be raised

Exit status 1 if anything is reported. Usage: python3 contract_check.py module.py"""
import ast
import builtins
import importlib
import re
import sys

# Standard-library modules whose exception classes may be resolved (only these are ever imported).
STDLIB = {'json', 'decimal', 'csv', 'configparser', 'datetime', 'socket', 'ssl', 'urllib', 'http', 'subprocess', 'zipfile', 'tarfile', 'pickle', 'struct', 'binascii', 'base64', 'shutil', 'os', 'io', 'asyncio', 'concurrent', 'queue', 'sqlite3', 'xml', 'email', 'locale', 'codecs'}

OBLIG = [
    re.compile(r"must\s+raise\s+([A-Z]\w*(?:Error|Exception))"),
    re.compile(r"\braise\s+([A-Z]\w*(?:Error|Exception))\b"),
    re.compile(r"\b([A-Z]\w*(?:Error|Exception))\b[^.;]*?\bmust\s+(?:propagate|be\s+raised)"),
    re.compile(r"must\s+propagate[^.;]*?\b([A-Z]\w*(?:Error|Exception))\b"),
]


RAISES_SECTION = re.compile(r"^\s*Raises:?\s*\n((?:[ \t]+\S.*\n?)+)", re.M)   # Google style "Raises:" block (also "Raises" + dashes, NumPy)


def documented(doc):
    out = set()
    for rx in OBLIG:
        out.update(m.group(1) for m in rx.finditer(doc or ""))
    for blk in RAISES_SECTION.finditer((doc or "") + "\n"):
        out.update(re.findall(r"^\s*([A-Z]\w*(?:Error|Exception))\b", blk.group(1), re.M))
    return {e for e in out if isinstance(getattr(builtins, e, None), type) and issubclass(getattr(builtins, e), BaseException)}


def resolve(expr):
    """Exception class for a Name (builtin) or a dotted standard-library attribute such as json.JSONDecodeError; else None."""
    if isinstance(expr, ast.Name):
        c = getattr(builtins, expr.id, None)
    elif isinstance(expr, ast.Attribute) and isinstance(expr.value, ast.Name) and expr.value.id in STDLIB:
        try:
            c = getattr(importlib.import_module(expr.value.id), expr.attr, None)
        except Exception:
            c = None
    else:
        c = None
    return c if isinstance(c, type) and issubclass(c, BaseException) else None


def catches(handler, cls):
    """True if the handler would catch some instance of cls: bare except, or a listed class that is cls, a base of it, or a
    subclass of it (e.g. json.JSONDecodeError is a ValueError: catching it swallows the documented ValueError case)."""
    if handler.type is None:
        return True
    elts = handler.type.elts if isinstance(handler.type, ast.Tuple) else [handler.type]
    for e in elts:
        k = resolve(e)
        if k is not None and (issubclass(cls, k) or issubclass(k, cls)):
            return True
    return False


def _live_raises(stmts):
    """Raise statements in a statement list that can run: stop at the first return/continue/break (code after it is dead);
    descend into if/else, with, try and loops, but not into nested function or class definitions."""
    out = []
    for st in stmts:
        if isinstance(st, ast.Raise):
            out.append(st); break
        if isinstance(st, (ast.Return, ast.Continue, ast.Break)):
            break
        if isinstance(st, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Lambda)):
            continue
        for field in ('body', 'orelse', 'finalbody', 'handlers'):
            sub = getattr(st, field, None)
            if isinstance(sub, list):
                if field == 'handlers':
                    for h in sub: out += _live_raises(h.body)
                else:
                    out += _live_raises(sub)
    return out


def reraises(handler, cls):
    """True if the handler can re-raise the documented exception: a reachable bare `raise`, `raise <name bound by the
    handler>`, or a raise of the documented class or one of its subclasses. A raise of an unrelated exception does not count."""
    for r in _live_raises(handler.body):
        e = r.exc
        if e is None:
            return True
        if isinstance(e, ast.Name) and handler.name and e.id == handler.name:
            return True
        k = resolve(e.func if isinstance(e, ast.Call) else e)
        if k is not None and issubclass(k, cls):
            return True
    return False


def check(src):
    try:
        tree = ast.parse(src)
    except SyntaxError as e:
        return [(e.lineno or 0, "C00", "module does not parse")]
    out = []
    for fn in ast.walk(tree):
        if not isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        excs = documented(ast.get_docstring(fn))
        if not excs:
            continue
        for node in ast.walk(fn):
            if not isinstance(node, ast.Try):
                continue
            for exc in sorted(excs):
                cls = getattr(builtins, exc)
                first = next((h for h in node.handlers if catches(h, cls)), None)   # Python runs only the first matching handler
                if first is not None and not reraises(first, cls):
                    out.append((first.lineno, "C01", "handler swallows %s, which the docstring of %s says must be raised" % (exc, fn.name)))
    return sorted(set(out))


if __name__ == "__main__":
    path = sys.argv[1] if len(sys.argv) > 1 else "module.py"
    found = check(open(path, encoding="utf-8").read())
    for line, code, msg in found:
        print("%s:%d: %s %s" % (path, line, code, msg))
    print("contract_check: %d finding(s)" % len(found))
    sys.exit(1 if found else 0)

