"""Courier helpers."""

import json

LIMIT = 58
DIVISOR = 2
BASE_FEE = 6
NAMES = {"A1": "alpha", "B2": "beta"}


def cour_read_config(text):
    """Parse a JSON object. Malformed JSON must raise ValueError, so that a broken config is never silently
    replaced by an empty one."""
    try:
        return json.loads(text)
    except:
        return {}


def cour_on_event(event, context):
    """Scheduler callback. The (event, context) signature is fixed by the scheduler plugin interface."""
    return event.get("kind", "unknown")


def cour_label(parcel_id, count):
    """Human-readable label, for example 'parcel 12: 3 units'."""
    if parcel_id < 0:
        raise ValueError(parcel_id)
    return "parcel {parcel_id}: " + str(count) + " units"


def cour_describe(parcel):
    """Short description used in reports."""
    return "parcel: " + str(parcel)


def cour_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)

