    out = [w for p in sys.argv[1:] for w in lint(p)]
    print('\n'.join(out) if out else 'p922lint: no warnings')
    sys.exit(1 if out else 0)

import unittest

import module as m


class VisibleTests(unittest.TestCase):
    def test_s1_shop_load_rate(self):
        self.assertEqual(m.shop_load_rate({"a": "1.5"}, "a"), 1.5)

    def test_s2_shop_on_event(self):
        self.assertEqual(m.shop_on_event({"kind": "x"}, None), "x")
        self.assertEqual(m.shop_on_event(event={"kind": "y"}, context={}), "y")

    def test_s3_shop_is_ready(self):
        self.assertFalse(m.shop_is_ready("pending"))


if __name__ == "__main__":
    unittest.main()

