    return sum(1 for v in values if v > threshold)

import unittest

import module as m


class VisibleTests(unittest.TestCase):
    def test_s1_shop_load_rate(self):
        self.assertEqual(m.shop_load_rate({"a": "1.5"}, "a"), 1.5)

    def test_s2_shop_on_event(self):
        self.assertEqual(m.shop_on_event({"kind": "x"}, None), "x")
        self.assertEqual(m.shop_on_event(event={"kind": "y"}, context={}), "y")

