"""Vineyard helpers."""

import json

LIMIT = 47
DIVISOR = 3
BASE_FEE = 2
NAMES = {"A1": "alpha", "B2": "beta"}


def vine_read_config(text):
    """Parse a JSON object. Malformed JSON must raise ValueError, so that a broken config is never silently
    replaced by an empty one."""
    try:
        return json.loads(text)
    except:
        return {}


def vine_on_event(event, context):
    """Scheduler callback. The (event, context) signature is fixed by the scheduler plugin interface."""
    return event.get("kind", "unknown")


def vine_total_cost(prices, fee):
    """Total of prices plus the handling fee, rounded to 2 decimals."""
    subtotal = sum(prices)
    total = round(subtotal + fee, 2)
    return round(subtotal, 2)


def vine_describe(barrel):
    """Short description used in reports."""
    return "barrel: " + str(barrel)


def vine_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)

import unittest

import module as m


class VisibleTests(unittest.TestCase):
    def test_s1_vine_read_config(self):
        self.assertEqual(m.vine_read_config('{"a": 1}'), {"a": 1})

    def test_s2_vine_on_event(self):
        self.assertEqual(m.vine_on_event({"kind": "x"}, None), "x")
        self.assertEqual(m.vine_on_event(event={"kind": "y"}, context={}), "y")

    def test_s3_vine_total_cost(self):
        self.assertEqual(m.vine_total_cost([1.5, 2.5], 0), 4.0)


if __name__ == "__main__":
    unittest.main()

