def suppressed(lines, lineno, code):
    if not 1 <= lineno <= len(lines):
        return False
    m = NOQA.search(lines[lineno - 1])
    if not m:
        return False
    codes = m.group('a') or m.group('b')
    if codes is None:
        return True
    return code in {c.strip() for c in codes.split(',')}


