import unittest

import module as m


class VisibleTests(unittest.TestCase):
    def test_s1_park_read_config(self):
        self.assertEqual(m.park_read_config('{"a": 1}'), {"a": 1})

    def test_s2_park_reminder_template(self):
        template, ref = m.park_reminder_template(58)
        self.assertEqual(template, "Reminder: permit {permit_id} is due")
        self.assertEqual(template.format(permit_id=ref), "Reminder: permit 58 is due")

    def test_s3_park_collect_permit(self):
        self.assertEqual(m.park_collect_permit("a", []), ["a"])
        self.assertEqual(m.park_collect_permit("b", ["a"]), ["a", "b"])


if __name__ == "__main__":
    unittest.main()

