import module as m


class VisibleTests(unittest.TestCase):
    def test_s1_fer_parse_qty(self):
        self.assertEqual(m.fer_parse_qty("7"), 7)
        with self.assertRaises(ValueError):
            m.fer_parse_qty("-1")

    def test_s2_fer_on_event(self):
        self.assertEqual(m.fer_on_event({"kind": "x"}, None), "x")
