"""Vineyard helpers."""

import json

LIMIT = 68
DIVISOR = 4
BASE_FEE = 2
NAMES = {"A1": "alpha", "B2": "beta"}


def vine_load_rate(table, key):
    """Return table[key] as a float. A missing key must raise KeyError so that callers can report it."""
    try:
        return float(table[key])
    except:
        pass
    return 0.0


def vine_reminder_template(barrel_id):
    """Return the reminder template and its id. The mailer renders the template later with str.format, so the
    placeholder must stay literal."""
    template = "Reminder: barrel {barrel_id} is due"
    return template, barrel_id


def vine_collect_barrel(barrel, batch=[]):
    """Append barrel to batch and return the batch; each call without a batch starts a new one."""
    batch.append(barrel)
    return batch


def vine_describe(barrel):
    """Short description used in reports."""
    return "barrel: " + str(barrel)


def vine_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)

